void main() {
  int n, num;
  print("First 20 Cullen numbers:");

  for (n = 1; n <= 20; n++) {
    num = n * (1 << n) + 1;
    print("$num ");
  }

  print("\n\nFirst 20 Woodall numbers:");

  for (n = 1; n <= 20; n++) {
    num = n * (1 << n) - 1;
    print("$num ");
  }
}

void main() {
  const double EPSILON = 1.0e-15;
  double fact = 1;
  double e = 2.0, e0;
  int n = 2;
  do {
    e0 = e;
    fact *= n++;
    e += 1.0 / fact;
  } while ((e-e0).abs() >= EPSILON);
  print('The value of e = $e');
}

